let state = { active: false, colorMode: 0 };
let tapCount = 0;
let tapTimeout = null;
let animatingColorShift = false;
let saveTimeout = null;
let lastKeyTime = 0;

const haptic = {
  light: () => navigator.vibrate?.(10),
  medium: () => navigator.vibrate?.(20),
  pattern: (arr) => navigator.vibrate?.(arr)
};

const getColorClass = (mode) => COLORS[mode % COLORS.length].class;
const getColorName = (mode) => COLORS[mode % COLORS.length].name;

const storage = {
  save() {
    clearTimeout(saveTimeout);
    saveTimeout = setTimeout(() => {
      try {
        localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
      } catch (e) {
        if (e.name === 'QuotaExceededError') {
          console.warn('Storage quota exceeded');
        }
      }
    }, CONFIG.saveDebounceDuration);
  },
  load() {
    try {
      const saved = localStorage.getItem(CONFIG.storageKey);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
          state = parsed;
        }
      }
    } catch (e) {
      // Silent failure - use default state
    }
  }

