const keyHandlers = {
  ' ': toggleActive,
  'enter': toggleActive,
  'escape': resetState,
  'c': cycleColor,
  'r': resetState,
  '?': modal.open
};

const handleKeyDown = (e) => {
  const handler = keyHandlers[e.key.toLowerCase()];
  if (handler) {
    const now = Date.now();
    if (now - lastKeyTime >= CONFIG.keyDebounce) {
      e.preventDefault();
      handler();
      lastKeyTime = now;
    }
  }
};

const handleModalKeyDown = (e) => {
  if (e.key === 'Escape') {
    e.preventDefault();
    modal.close();
  }
};

